package android.view; import java.util.*; public class ViewGroup extends View { public static class LayoutParams {public LayoutParams(int w,int h){}} public final List<View> children=new ArrayList<>(); public ViewGroup(android.content.Context c){super(c);} public void addView(View v){children.add(v);v.parent=this;} public void addView(View v,LayoutParams p){addView(v);} public void addView(View v,int i,LayoutParams p){children.add(i,v);v.parent=this;} public void removeView(View v){children.remove(v);v.parent=null;v.onDetachedFromWindow();} public void setClipChildren(boolean b){} }
